int process_component(mif_hdr_t *hdr, char *buf) {
    component_t comp;
    tv_parser_t parser;
    int ret = -1;

    // Initialize component and parser
    memset(&comp, 0, sizeof(comp));
    tv_parser_init(&parser, buf);

    // Parse required attributes
    comp.x = tv_parser_get_int(&parser, "X", -1);
    comp.y = tv_parser_get_int(&parser, "Y", -1);
    comp.width = tv_parser_get_int(&parser, "Width", -1);
    comp.height = tv_parser_get_int(&parser, "Height", -1);
    comp.xsample = tv_parser_get_int(&parser, "XSample", -1);
    comp.ysample = tv_parser_get_int(&parser, "YSample", -1);
    comp.precision = tv_parser_get_int(&parser, "Precision", -1);
    comp.sign = tv_parser_get_int(&parser, "Sign", -1);
    comp.data = tv_parser_get_string(&parser, "Data", NULL);

    if (comp.x == -1 || comp.y == -1 || comp.width == -1 || comp.height == -1 ||
        comp.xsample == -1 || comp.ysample == -1 || comp.precision == -1 || comp.sign == -1 || !comp.data) {
        // Required attributes missing
        if (comp.data) {
            free(comp.data);
        }
        return -1;
    }

    // Create component
    if (component_create(&comp) != 0) {
        if (comp.data) {
            free(comp.data);
        }
        return -1;
    }

    // Add component to header
    if (hdr_add_component(hdr, &comp) != 0) {
        if (comp.data) {
            free(comp.data);
        }
        return -1;
    }

    ret = 0;
    return ret;
}

int process_component(mif_hdr_t *hdr, char *buf) {
    mif_component_t comp;
    tv_parser_t parser;
    int ret = -1;

    memset(&comp, 0, sizeof(comp));
    tv_parser_init(&parser, buf);

    comp.top_left.x = tv_parser_get_int(&parser, "TLX");
    comp.top_left.y = tv_parser_get_int(&parser, "TLY");
    comp.width = tv_parser_get_int(&parser, "W");
    comp.height = tv_parser_get_int(&parser, "H");

    if (comp.top_left.x == INT_MIN || comp.top_left.y == INT_MIN ||
        comp.width == INT_MIN || comp.height == INT_MIN) {
        goto cleanup;
    }

    comp.sample_rate = tv_parser_get_int(&parser, "SR");
    comp.precision = tv_parser_get_int(&parser, "P");
    comp.sign = tv_parser_get_int(&parser, "S");

    if (comp.sample_rate == INT_MIN || comp.precision == INT_MIN || comp.sign == INT_MIN) {
        goto cleanup;
    }

    comp.data = tv_parser_get_string(&parser, "D");
    if (!comp.data) {
        goto cleanup;
    }

    if (mif_component_create(hdr, &comp) != 0) {
        goto cleanup;
    }

    ret = 0;
cleanup:
    tv_parser_cleanup(&parser);
    return ret;
}

int process_mif_component(mif_hdr_t *hdr, char *buf) {
    mif_component_t comp;
    tv_parser_t parser;
    int ret = -1;

    // Initialize component and TV parser
    tv_parser_init(&parser, buf);

    // Parse component attributes
    comp.top_left_x = tv_get_int(&parser, "top_left_x");
    comp.top_left_y = tv_get_int(&parser, "top_left_y");
    comp.width = tv_get_int(&parser, "width");
    comp.height = tv_get_int(&parser, "height");
    comp.sample_rate_x = tv_get_int(&parser, "sample_rate_x");
    comp.sample_rate_y = tv_get_int(&parser, "sample_rate_y");
    comp.precision = tv_get_int(&parser, "precision");
    comp.is_signed = tv_get_bool(&parser, "is_signed");
    comp.data = tv_get_string(&parser, "data");

    // Check for missing required attributes
    if (comp.top_left_x == INT_MIN || comp.top_left_y == INT_MIN ||
        comp.width == INT_MIN || comp.height == INT_MIN ||
        comp.sample_rate_x == INT_MIN || comp.sample_rate_y == INT_MIN ||
        comp.precision == INT_MIN || comp.data == NULL) {
        goto cleanup;
    }

    // Create component and add to header
    if (mif_component_create(hdr, &comp) != 0) {
        goto cleanup;
    }

    ret = 0;

cleanup:
    tv_parser_cleanup(&parser);
    if (comp.data) {
        free(comp.data);
    }
    return ret;
}

int process_mif_component(mif_hdr_t *hdr, char *buf) {
    mif_component_t comp;
    tv_parser_t parser;
    int ret = -1;

    memset(&comp, 0, sizeof(comp));
    tv_parser_init(&parser, buf);

    if (!tv_parser_get_int(&parser, "TLX", &comp.tlx)) {
        goto error;
    }
    if (!tv_parser_get_int(&parser, "TLY", &comp.tly)) {
        goto error;
    }
    if (!tv_parser_get_int(&parser, "WIDTH", &comp.width)) {
        goto error;
    }
    if (!tv_parser_get_int(&parser, "HEIGHT", &comp.height)) {
        goto error;
    }
    if (!tv_parser_get_int(&parser, "SRX", &comp.srx)) {
        goto error;
    }
    if (!tv_parser_get_int(&parser, "SRY", &comp.sry)) {
        goto error;
    }
    if (!tv_parser_get_int(&parser, "PRECISION", &comp.precision)) {
        goto error;
    }
    if (!tv_parser_get_int(&parser, "SIGN", &comp.sign)) {
        goto error;
    }

    if (!tv_parser_get_data(&parser, "DATA", comp.data, sizeof(comp.data))) {
        goto error;
    }

    if (mif_component_create(hdr, &comp) < 0) {
        goto error;
    }

    ret = 0;

error:
    if (ret < 0) {
        // Cleanup if necessary
    }

    return ret;
}

